using CustomCodeFramework.Core.Results;using CustomCodeFramework.Cqrs.Queries;using Dhole.Content.Application.Abstractions.Cache;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Application.Mappings;using Dhole.Content.Contracts.Navigation;using Dhole.Content.Domain.Shared;namespace Dhole.Content.Application.Navigation.GetNavigationMenu;public sealed class GetNavigationMenuQueryHandler(INavigationMenuRepository repo,IContentCacheService cache):IQueryHandler<GetNavigationMenuQuery,Result<NavigationMenuDto>>{public async Task<Result<NavigationMenuDto>> HandleAsync(GetNavigationMenuQuery q,CancellationToken ct=default){var site=string.IsNullOrWhiteSpace(q.SiteKey)?ContentConstants.DefaultSiteKey:q.SiteKey.Trim();var location=q.Location.Trim().ToLowerInvariant();var cached=await cache.GetMenuAsync(site,location,ct);if(cached is not null)return Result.Success(cached);var x=await repo.GetByLocationAsync(site,location,ct);if(x is null||x.IsDeleted||!x.IsActive)return Result.Failure<NavigationMenuDto>(ContentErrors.MenuNotFound);var dto=ContentMappings.ToDto(x);await cache.SetMenuAsync(site,location,dto,cancellationToken:ct);return Result.Success(dto);}}
